public <T, H extends FullResponseHolder<T>> H go(Request request, HttpResponseHandler<H, H> responseHandler)
    throws IOException, InterruptedException
{
  return go(request, responseHandler, Collections.emptySet());
}

/**
 * Executes a Request object aimed at the leader. Throws IOException if the leader cannot be located.
 * Any response which is not OK(200) and is not part of the passed in statusesToNotHandle is treated as a
 * failure and a best-effort retry is done by refreshing the cached leader. If the retries are still
 * unsuccessful, an IOException is thrown.
 */
public <T, H extends FullResponseHolder<T>> H go(
    Request request,
    HttpResponseHandler<H, H> responseHandler,
    Set<HttpResponseStatus> statusesToNotHandle
)
    throws IOException, InterruptedException
{
  Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
  for (int counter = 0; counter < MAX_RETRIES; counter++) {
    final H fullResponseHolder;
    try {
      try {
        fullResponseHolder = httpClient.go(request, responseHandler).get();
      }
      catch (ExecutionException e) {
        // Unwrap IOExceptions and ChannelExceptions, re-throw others
        Throwables.propagateIfInstanceOf(e.getCause(), IOException.class);
        Throwables.propagateIfInstanceOf(e.getCause(), ChannelException.class);
        throw new RE(e, "HTTP request to[%s] failed", request.getUrl());
      }
    }
    catch (IOException | ChannelException ex) {
      // can happen if the node is stopped.
      log.warn(ex, "Request[%s] failed.", request.getUrl());
      Iterator<DiscoveryDruidNode> nodeIterator = druidNodeDiscovery.getAllNodes().iterator();
      String leader = null;
      if (nodeIterator.hasNext()) {
        DiscoveryDruidNode discoveryNode = nodeIterator.next();
        DruidNode druidNode = discoveryNode.getDruidNode();
        String nodeHost = druidNode.getHost();
        int tlsPort = druidNode.getTlsPort();
        int plaintextPort = druidNode.getPlaintextPort();
        boolean tlsEnabled = druidNode.isEnableTlsPort();
        boolean plaintextEnabled = druidNode.isEnablePlaintextPort();
        String serviceScheme = tlsPort >= 0 ? "https" : "http";
        String hostAndPortToUse = null;
        if (tlsEnabled) {
          hostAndPortToUse = HostAndPort.fromParts(nodeHost, tlsPort).toString();
        } else if (plaintextEnabled && plaintextPort < 0) {
          hostAndPortToUse = HostAndPort.fromString(nodeHost).toString();
        } else if (plaintextEnabled) {
          hostAndPortToUse = HostAndPort.fromParts(nodeHost, plaintextPort).toString();
        }
        leader = StringUtils.format("%s://%s", serviceScheme, hostAndPortToUse);
      }
      currentKnownLeader.set(leader);
      if (leader == null) {
        throw new IOE("No known server");
      }
      try {
        request = withUrl(request, leader);
        continue;
      }
      catch (MalformedURLException e) {
        // Not an IOException; this is our own fault.
        throw new ISE(
            e,
            "failed to build url with path[%] and query string [%s].",
            request.getUrl().getPath(),
            request.getUrl().getQuery()
        );
      }
    }

    HttpResponseStatus responseStatus = fullResponseHolder.getResponse().getStatus();
    if (HttpResponseStatus.TEMPORARY_REDIRECT.equals(responseStatus)) {
      String redirectUrlStr = fullResponseHolder.getResponse().headers().get("Location");
      if (redirectUrlStr == null) {
        throw new IOE("No redirect location is found in response from url[%s].", request.getUrl());
      }

      log.info("Request[%s] received redirect response to location [%s].", request.getUrl(), redirectUrlStr);

      final URL redirectUrl;
      try {
        redirectUrl = new URL(redirectUrlStr);
      }
      catch (MalformedURLException ex) {
        throw new IOE(
            ex,
            "Malformed redirect location is found in response from url[%s], new location[%s].",
            request.getUrl(),
            redirectUrlStr
        );
      }

      //update known leader location
      currentKnownLeader.set(StringUtils.format(
          "%s://%s:%s",
          redirectUrl.getProtocol(),
          redirectUrl.getHost(),
          redirectUrl.getPort()
      ));

      request = withUrl(request, redirectUrl);
    } else if (HttpResponseStatus.OK.equals(responseStatus) || statusesToNotHandle.contains(responseStatus)) {
      return fullResponseHolder;
    } else {
      // can happen if the leader changed or the request was served by a proxy/sidecar which could not reach
      // the intended endpoint. Do a best-effort retry by refreshing the cached leader.
      log.warn(
          "Request[%s] received response with status[%s], retrying after refreshing cached leader.",
          request.getUrl(),
          responseStatus
      );
      currentKnownLeader.set(null);
      try {
        request = withUrl(request, getCurrentKnownLeader(false));
      }
      catch (MalformedURLException e) {
        // Not an IOException; this is our own fault.
        throw new ISE(
            e,
            "failed to build url with path[%] and query string [%s].",
            request.getUrl().getPath(),
            request.getUrl().getQuery()
        );
      }
    }
  }

  throw new IOE("Retries exhausted, couldn't fulfill request to [%s].", request.getUrl());
}

